package com.autohub.app;

import android.app.*;
import android.os.Bundle;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.ColorDrawable;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
    AutoHubView ui;
    final String PREF="autohub";
    @Override public void onCreate(Bundle b){ super.onCreate(b); ui=new AutoHubView(this); setContentView(ui); applyBars(); }
    void applyBars(){ boolean light=ui.light; int c=light?Color.rgb(242,245,248):Color.rgb(7,9,13); getWindow().setStatusBarColor(c); getWindow().setNavigationBarColor(c); getWindow().getDecorView().setSystemUiVisibility(light?(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR):0); }
    String pref(String k,String d){return getSharedPreferences(PREF,0).getString(k,d);} void put(String k,String v){getSharedPreferences(PREF,0).edit().putString(k,v).apply();}
    ArrayList<String> rows(String key){String s=pref(key,""); ArrayList<String> a=new ArrayList<>(); if(!s.isEmpty()) Collections.addAll(a,s.split("\\n")); return a;}
    void add(String key,String row){String old=pref(key,""); put(key,old.isEmpty()?row:old+"\n"+row); ui.invalidate();}
    String today(){return new SimpleDateFormat("dd.MM.yyyy",Locale.getDefault()).format(new Date());}
    String clean(String s){return s.replace("|","/").replace("\n"," ").trim();}
    EditText field(LinearLayout l,String hint,String value){EditText e=new EditText(this); e.setHint(hint);e.setText(value);e.setSingleLine(true);e.setTextSize(15);e.setPadding(0,12,0,8);l.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
    LinearLayout form(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(24,4,24,0);return l;}
    void saveVehicle(){LinearLayout l=form();EditText n=field(l,"Марка и модель",pref("vehicle","Мой автомобиль"));EditText e=field(l,"Двигатель",pref("engine",""));EditText y=field(l,"Год",pref("year",""));EditText m=field(l,"Пробег, км",pref("mileage","0")); new AlertDialog.Builder(this).setTitle("Профиль автомобиля").setView(l).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->{put("vehicle",clean(n.getText().toString()));put("engine",clean(e.getText().toString()));put("year",clean(y.getText().toString()));put("mileage",clean(m.getText().toString()));ui.invalidate();}).show();}
    void addService(){LinearLayout l=form();EditText t=field(l,"Работа / обслуживание","");EditText cost=field(l,"Стоимость, ₽","0");EditText km=field(l,"Пробег, км",pref("mileage","0"));EditText next=field(l,"Следующее ТО, км (необязательно)","");EditText c=field(l,"Сервис / комментарий",""); new AlertDialog.Builder(this).setTitle("Новое обслуживание").setView(l).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->{add("service",today()+"|"+clean(t.getText().toString())+"|"+clean(cost.getText().toString())+"|"+clean(km.getText().toString())+"|"+clean(next.getText().toString())+"|"+clean(c.getText().toString())); toast("ТО сохранено");}).show();}
    void addFuel(){LinearLayout l=form();EditText liters=field(l,"Литры","0");EditText price=field(l,"Цена за литр, ₽","0");EditText km=field(l,"Пробег, км",pref("mileage","0"));EditText station=field(l,"АЗС / комментарий",""); new AlertDialog.Builder(this).setTitle("Новая заправка").setView(l).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->{add("fuel",today()+"|"+clean(liters.getText().toString())+"|"+clean(price.getText().toString())+"|"+clean(km.getText().toString())+"|"+clean(station.getText().toString()));toast("Заправка сохранена");}).show();}
    void addExpense(){LinearLayout l=form();EditText cat=field(l,"Категория","ТО");EditText sum=field(l,"Сумма, ₽","0");EditText km=field(l,"Пробег, км",pref("mileage","0"));EditText c=field(l,"Комментарий",""); new AlertDialog.Builder(this).setTitle("Новый расход").setView(l).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->{add("expense",today()+"|"+clean(cat.getText().toString())+"|"+clean(sum.getText().toString())+"|"+clean(km.getText().toString())+"|"+clean(c.getText().toString()));toast("Расход сохранён");}).show();}
    void addReminder(){LinearLayout l=form();EditText title=field(l,"Что напомнить","");EditText date=field(l,"Дата (дд.мм.гггг)",today());EditText km=field(l,"Пробег (необязательно)",""); new AlertDialog.Builder(this).setTitle("Напоминание").setView(l).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->{add("reminder",clean(title.getText().toString())+"|"+clean(date.getText().toString())+"|"+clean(km.getText().toString())+"|0");toast("Напоминание создано");}).show();}
    void addProblem(){LinearLayout l=form();EditText title=field(l,"Проблема","");EditText desc=field(l,"Описание","");EditText km=field(l,"Пробег",pref("mileage","0")); new AlertDialog.Builder(this).setTitle("Проблема автомобиля").setView(l).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->{add("problem",today()+"|"+clean(title.getText().toString())+"|"+clean(desc.getText().toString())+"|"+clean(km.getText().toString())+"|Новая");toast("Проблема добавлена");}).show();}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}

    class AutoHubView extends View {
        Paint p=new Paint(Paint.ANTI_ALIAS_FLAG); Path path=new Path(); RectF r=new RectF();
        int page=0; boolean light; float downX,downY; final int blue=Color.rgb(38,145,255), cyan=Color.rgb(102,205,255), green=Color.rgb(38,205,143), orange=Color.rgb(255,171,58), red=Color.rgb(255,78,94);
        final String[] nav={"Главная","ТО","Расходы","Авто","Ещё"};
        AutoHubView(Context c){super(c);light=getSharedPreferences(PREF,0).getBoolean("light",false);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
        float d(){return getResources().getDisplayMetrics().density;} int bg(){return light?Color.rgb(242,245,248):Color.rgb(7,9,13);} int fg(){return light?Color.rgb(23,29,36):Color.rgb(245,248,252);} int sub(){return light?Color.rgb(91,103,116):Color.rgb(151,166,183);} int glass(){return light?Color.argb(210,255,255,255):Color.argb(188,16,23,33);}
        String pv(String k,String d){return pref(k,d);} int count(String k){return rows(k).size();}
        void txt(Canvas c,String s,float x,float y,float size,int col,boolean bold){p.setShader(null);p.setStyle(Paint.Style.FILL);p.setColor(col);p.setTextSize(size*d());p.setTypeface(Typeface.create("sans",bold?Typeface.BOLD:Typeface.NORMAL));c.drawText(s,x,y,p);}
        void glass(Canvas c,float l,float t,float rr,float bb,float rad){r.set(l,t,rr,bb);p.setStyle(Paint.Style.FILL);p.setColor(glass());p.setShadowLayer(22*d(),0,8*d(),light?Color.argb(30,30,55,80):Color.argb(85,0,80,210));c.drawRoundRect(r,rad*d(),rad*d(),p);p.clearShadowLayer();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(d());p.setColor(light?Color.argb(180,255,255,255):Color.argb(130,82,148,215));c.drawRoundRect(r,rad*d(),rad*d(),p);p.setStyle(Paint.Style.FILL);p.setShader(new LinearGradient(l,t,rr,t+80*d(),light?Color.argb(110,255,255,255):Color.argb(85,125,200,255),Color.TRANSPARENT,Shader.TileMode.CLAMP));c.drawRoundRect(r,rad*d(),rad*d(),p);p.setShader(null);}
        void dot(Canvas c,float x,float y,int col){p.setStyle(Paint.Style.FILL);p.setColor(col);p.setShadowLayer(10*d(),0,0,Color.argb(120,Color.red(col),Color.green(col),Color.blue(col)));c.drawCircle(x,y,4*d(),p);p.clearShadowLayer();}
        @Override protected void onDraw(Canvas c){c.drawColor(bg());float D=d();p.setShader(new RadialGradient(getWidth()*.68f,90*D,360*D,light?Color.argb(70,55,135,230):Color.argb(95,0,105,255),Color.TRANSPARENT,Shader.TileMode.CLAMP));c.drawRect(0,0,getWidth(),getHeight()*.72f,p);p.setShader(null);header(c);switch(page){case 0:home(c);break;case 1:service(c);break;case 2:finance(c);break;case 3:vehicle(c);break;default:more(c);}bottom(c);}
        void header(Canvas c){float D=d();txt(c,"AUTO HUB",20*D,31*D,11,sub(),true);txt(c,title(),20*D,67*D,27,fg(),true);dot(c,getWidth()-44*D,28*D,green);}
        String title(){return page==0?pv("vehicle","Мой автомобиль"):nav[page];}
        void home(Canvas c){float D=d();String veh=pv("vehicle","Мой автомобиль");String km=pv("mileage","0");glass(c,16*D,88*D,getWidth()-16*D,302*D,26);txt(c,veh,32*D,122*D,22,fg(),true);txt(c,pv("engine","Двигатель не указан"),32*D,146*D,11,sub(),false); // stylized car
            p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3*D);p.setColor(cyan);path.reset();path.moveTo(45*D,220*D);path.lineTo(60*D,190*D);path.lineTo(84*D,178*D);path.lineTo(190*D,178*D);path.lineTo(224*D,198*D);path.lineTo(255*D,220*D);path.lineTo(45*D,220*D);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);p.setColor(light?Color.rgb(230,236,242):Color.rgb(23,31,42));c.drawRoundRect(new RectF(90*D,186*D,178*D,205*D),7*D,7*D,p);p.setStyle(Paint.Style.STROKE);p.setColor(cyan);c.drawLine(132*D,186*D,132*D,205*D,p);p.setStyle(Paint.Style.FILL);c.drawCircle(82*D,220*D,13*D,p);c.drawCircle(215*D,220*D,13*D,p);
            txt(c,km,32*D,268*D,28,fg(),true);txt(c,"км  ·  текущий пробег",32*D,288*D,10,sub(),false);txt(c,count("service")==0?"Нет ближайшего ТО":count("service")+" записей ТО",getWidth()-154*D,265*D,11,count("service")==0?sub():green,true);txt(c,"Сервисная книга",getWidth()-154*D,286*D,9,sub(),false);
            cardMetric(c,16,320,"ТО",count("service"),green);cardMetric(c,126,320,"ТОПЛИВО",count("fuel"),cyan);cardMetric(c,236,320,"РАСХОДЫ",count("expense"),orange);
            txt(c,"Быстрые действия",20*D,440*D,18,fg(),true);quick(c,16,454,"+ ТО",blue);quick(c,126,454,"+ Топливо",green);quick(c,236,454,"+ Расход",orange);quick(c,126,522,"+ Напомнить",cyan);
            glass(c,16*D,590*D,getWidth()-16*D,650*D,18);txt(c,"Данные на устройстве · без выдуманных значений",30*D,615*D,10,sub(),false);
        }
        void cardMetric(Canvas c,int x,int y,String label,int n,int col){float D=d();glass(c,x*D,y*D,(x+101)*D,(y+94)*D,18);txt(c,label,x*D+14*D,(y+24)*D,9,sub(),true);txt(c,String.valueOf(n),x*D+14*D,(y+56)*D,22,fg(),true);txt(c,"записей",x*D+14*D,(y+76)*D,9,sub(),false);dot(c,(x+84)*D,(y+22)*D,col);}
        void quick(Canvas c,int x,int y,String label,int col){float D=d();glass(c,x*D,y*D,(x+101)*D,(y+56)*D,16);dot(c,(x+18)*D,(y+28)*D,col);txt(c,label,(x+30)*D,(y+33)*D,10,fg(),true);}
        void service(Canvas c){float D=d();txt(c,"Сервисная книга",20*D,101*D,12,sub(),true);String[] names={"Последние работы","Запланированное ТО","Проблемы"};for(int i=0;i<3;i++){float y=112+i*58;glass(c,16*D,y*D,getWidth()-16*D,(y+49)*D,16);txt(c,names[i],32*D,(y+22)*D,13,fg(),true);int n=i==0?count("service"):i==2?count("problem"):0;txt(c,n==0?"Нет данных":n+" записей",32*D,(y+40)*D,9,sub(),false);txt(c,"›",getWidth()-40*D,(y+31)*D,20,sub(),false);}txt(c,"История",20*D,309*D,18,fg(),true);ArrayList<String> a=rows("service");int shown=0;for(int i=a.size()-1;i>=0&&shown<4;i--){String[] q=a.get(i).split("\\|",-1);if(q.length<6)continue;float y=326+shown*63;glass(c,16*D,y*D,getWidth()-16*D,(y+52)*D,15);txt(c,q[1],32*D,(y+22)*D,12,fg(),true);txt(c,q[0]+"  ·  "+q[3]+" км",32*D,(y+40)*D,9,sub(),false);txt(c,q[2]+" ₽",getWidth()-102*D,(y+29)*D,11,fg(),true);shown++;}glass(c,16*D,596*D,getWidth()-16*D,650*D,18);txt(c,"+ Добавить обслуживание",32*D,630*D,12,blue,true);}
        void finance(Canvas c){float D=d();int f=count("fuel"),e=count("expense");double total=0;for(String s:rows("expense")){String[] q=s.split("\\|",-1);if(q.length>2)total+=num(q[2]);}for(String s:rows("fuel")){String[] q=s.split("\\|",-1);if(q.length>2)total+=num(q[1])*num(q[2]);}glass(c,16*D,92*D,getWidth()-16*D,216*D,23);txt(c,"ВСЕГО ПО СОХРАНЁННЫМ ОПЕРАЦИЯМ",32*D,121*D,9,sub(),true);txt(c,String.format(Locale.getDefault(),"%.0f ₽",total),32*D,160*D,28,fg(),true);txt(c,"Рассчитано только из ваших записей",32*D,188*D,10,sub(),false);txt(c,"Топливо",20*D,252*D,18,fg(),true);metricRow(c,268,"Заправок",f,cyan);metricRow(c,328,"Расходов",e,orange);metricRow(c,388,"ТО",count("service"),green);txt(c,"Последние операции",20*D,480*D,18,fg(),true);ArrayList<String> a=rows("expense");for(int i=Math.max(0,a.size()-2);i<a.size();i++){String[] q=a.get(i).split("\\|",-1);float y=494+(i-(Math.max(0,a.size()-2)))*60;glass(c,16*D,y*D,getWidth()-16*D,(y+48)*D,15);if(q.length>=5){txt(c,q[1],32*D,(y+21)*D,12,fg(),true);txt(c,q[0]+" · "+q[3]+" км",32*D,(y+38)*D,9,sub(),false);txt(c,q[2]+" ₽",getWidth()-100*D,(y+28)*D,11,fg(),true);}}}
        double num(String s){try{return Double.parseDouble(s.replace(',','.').replace(" ",""));}catch(Exception e){return 0;}}
        void metricRow(Canvas c,int y,String label,int n,int col){float D=d();glass(c,16*D,y*D,getWidth()-16*D,(y+48)*D,15);dot(c,34*D,(y+24)*D,col);txt(c,label,50*D,(y+29)*D,12,fg(),true);txt(c,String.valueOf(n),getWidth()-60*D,(y+29)*D,13,fg(),true);}
        void vehicle(Canvas c){float D=d();glass(c,16*D,92*D,getWidth()-16*D,220*D,23);txt(c,pv("vehicle","Мой автомобиль"),32*D,126*D,21,fg(),true);txt(c,pv("engine","Двигатель не указан"),32*D,151*D,11,sub(),false);txt(c,pv("year","Год не указан"),32*D,172*D,11,sub(),false);txt(c,pv("mileage","0")+" км",32*D,204*D,21,fg(),true);txt(c,"Профиль",getWidth()-88*D,126*D,10,blue,true);String[] rs={"Сервисная история","Напоминания","Документы","Шины","Проблемы","Статистика"};for(int i=0;i<rs.length;i++){float y=238+i*55;glass(c,16*D,y*D,getWidth()-16*D,(y+46)*D,15);txt(c,rs[i],34*D,(y+29)*D,13,fg(),true);txt(c,"›",getWidth()-40*D,(y+30)*D,20,sub(),false);}}
        void more(Canvas c){float D=d();txt(c,"Центр управления",20*D,101*D,12,sub(),true);String[] rs={"Автомобиль","Уведомления","Единицы измерения","Резервная копия","Экспорт данных","Тема интерфейса"};for(int i=0;i<rs.length;i++){float y=112+i*54;glass(c,16*D,y*D,getWidth()-16*D,(y+45)*D,15);txt(c,rs[i],34*D,(y+29)*D,13,fg(),true);if(i==5)txt(c,light?"Светлая":"Тёмная",getWidth()-92*D,(y+29)*D,10,blue,true);else txt(c,"›",getWidth()-40*D,(y+30)*D,20,sub(),false);}glass(c,16*D,466*D,getWidth()-16*D,528*D,18);txt(c,light?"Переключить на тёмную":"Переключить на светлую",34*D,503*D,12,fg(),true);glass(c,16*D,542*D,getWidth()-16*D,604*D,18);txt(c,"Добавить проблему",34*D,579*D,12,red,true);txt(c,"AUTO HUB · Premium Mirror Glass",20*D,635*D,9,sub(),false);}
        void bottom(Canvas c){float D=d();float y=getHeight()/D-72;glass(c,10*D,y*D,getWidth()-10*D,(y+58)*D,23);for(int i=0;i<5;i++){float x=getWidth()*(i+.5f)/5;int col=i==page?blue:sub();if(i==page){p.setColor(light?Color.argb(38,38,145,255):Color.argb(48,38,145,255));p.setStyle(Paint.Style.FILL);c.drawCircle(x,(y+27)*D,21*D,p);}txt(c,nav[i],x-(nav[i].length()*3.0f)*D,(y+35)*D,8,col,i==page);}}
        @Override public boolean onTouchEvent(MotionEvent e){float D=d();if(e.getAction()==MotionEvent.ACTION_DOWN){downX=e.getX();downY=e.getY();return true;}if(e.getAction()!=MotionEvent.ACTION_UP)return true;float x=e.getX(),y=e.getY();if(Math.abs(x-downX)>90*D){page=x<downX?Math.min(4,page+1):Math.max(0,page-1);invalidate();return true;}if(y>getHeight()-78*D){int n=(int)(x/(getWidth()/5f));if(n>=0&&n<5){page=n;invalidate();}return true;}if(page==0){if(y>440*D&&y<520*D){if(x<116*D)addService();else if(x<230*D)addFuel();else addExpense();return true;}if(y>510*D&&y<590*D){addReminder();return true;}if(y>88*D&&y<310*D){saveVehicle();return true;}}else if(page==1&&y>575*D){addService();return true;}else if(page==3&&y>88*D&&y<225*D){saveVehicle();return true;}else if(page==4){if(y>110*D&&y<180*D){saveVehicle();return true;}if(y>445*D&&y<535*D){light=!light;put("light",String.valueOf(light));applyBars();invalidate();return true;}if(y>535*D&&y<625*D){addProblem();return true;}}return true;}
    }
}
